"""Exhaustively check the quadratic cover family generated by co-singletons."""

from __future__ import annotations

from itertools import combinations


def filters_for(n: int) -> list[tuple[tuple[int, int], int]]:
    full = (1 << n) - 1
    result = []
    for i, j in combinations(range(n), 2):
        left_witness = full ^ (1 << i)
        right_witness = full ^ (1 << j)
        family = 0
        for subset in range(1 << n):
            if (subset & left_witness) == left_witness or (subset & right_witness) == right_witness:
                family |= 1 << subset
        result.append(((i, j), family))
    return result


def main() -> None:
    for n in range(2, 9):
        filters = filters_for(n)
        full = (1 << n) - 1
        max_coverage = 0
        pair_checks = 0
        for left in range(1 << n):
            for right in range(1 << n):
                intersection = left & right
                covered = 0
                for index, (_edge, family) in enumerate(filters):
                    if (
                        ((family >> left) & 1)
                        and ((family >> right) & 1)
                        and not ((family >> intersection) & 1)
                    ):
                        covered |= 1 << index
                pair_checks += 1
                max_coverage = max(max_coverage, covered.bit_count())
                assert covered.bit_count() <= 1, (n, left, right, covered)

        # The explicit co-singleton endpoint pair covers each edge-filter.
        for index, ((i, j), family) in enumerate(filters):
            left = full ^ (1 << i)
            right = full ^ (1 << j)
            assert ((family >> left) & 1) and ((family >> right) & 1)
            assert not ((family >> (left & right)) & 1)

        print(
            f"n={n}; filters={len(filters)}; endpoint_pairs_checked={pair_checks}; "
            f"max_pair_coverage={max_coverage}; exact_cover_number={len(filters)}"
        )
    print("PASS: the family has exact cover number binomial(n,2) on each tested universe.")


if __name__ == "__main__":
    main()
